import time
from dispatchiq.helpers import route_cost, drop_until_feasible


def replan(state):
    t_start = time.time()
    TIME_LIMIT = 0.42

    def time_left():
        return (time.time() - t_start) < TIME_LIMIT

    jobs = state["jobs"]
    techs = state["techs"]
    healthy = [t for t in techs if not t["sick"]]
    result = {t["id"]: [] for t in techs}
    if not healthy:
        return result

    sick_ids = {t["id"] for t in techs if t["sick"]}
    tech_by_id = {t["id"]: t for t in healthy}
    healthy_ids = [t["id"] for t in healthy]
    tech_skills = {t["id"]: set(t["skills"]) for t in healthy}
    INFEAS = 1e6

    all_ids = sorted(jobs.keys())
    priority = {j: jobs[j]["priority"] for j in all_ids}
    jskill = {j: jobs[j]["skill"] for j in all_ids}
    pen = {j: 150.0 * jobs[j]["priority"] for j in all_ids}
    is_em = {j: bool(jobs[j].get("emergency")) for j in all_ids}
    morning = {j: jobs[j].get("morning_tech") for j in all_ids}

    elig = {j: [t["id"] for t in healthy if jskill[j] in tech_skills[t["id"]]]
            for j in all_ids}

    def moved_cost(jid, tid):
        mt = morning[jid]
        if mt is None or mt in sick_ids:
            return 0.0
        return 20.0 if mt != tid else 0.0

    _cache = {}

    def rc(tid, seq):
        if not seq:
            return 0.0
        key = (tid, tuple(seq))
        v = _cache.get(key)
        if v is None:
            v = route_cost(state, tech_by_id[tid], seq)
            _cache[key] = v
        return v

    def moved_sum(tid, seq):
        s = 0.0
        for x in seq:
            s += moved_cost(x, tid)
        return s

    def tech_cost(tid, seq):
        c = rc(tid, seq)
        if c >= INFEAS:
            return INFEAS
        return c + moved_sum(tid, seq)

    def total_cost(plan):
        c = 0.0
        sched = set()
        for tid in healthy_ids:
            seq = plan[tid]
            tc = tech_cost(tid, seq)
            if tc >= INFEAS:
                tc = 1e9
            c += tc
            sched.update(seq)
        for j in all_ids:
            if j not in sched:
                c += pen[j]
        return c

    # ------------------------------------------------------------------
    # insertion / ejection helpers (from champion)
    # ------------------------------------------------------------------
    def best_insertion(plan, jid):
        p = pen[jid]
        skill = jskill[jid]
        best = None
        for tid in healthy_ids:
            if skill not in tech_skills[tid]:
                continue
            seq = plan[tid]
            base_c = rc(tid, seq)
            if base_c >= INFEAS:
                continue
            base_m = moved_sum(tid, seq)
            old = base_c + base_m
            add_m = moved_cost(jid, tid)
            for pos in range(len(seq) + 1):
                ns = seq[:pos] + [jid] + seq[pos:]
                nc = rc(tid, ns)
                if nc >= INFEAS:
                    continue
                delta = (nc + base_m + add_m) - old - p
                if best is None or delta < best[0]:
                    best = (delta, tid, ns)
        return best

    def compute_reinsert_deltas(plan):
        d = {}
        for tid in healthy_ids:
            for v in plan[tid]:
                bv = None
                skill = jskill[v]
                for tid2 in healthy_ids:
                    if tid2 == tid:
                        continue
                    if skill not in tech_skills[tid2]:
                        continue
                    seq2 = plan[tid2]
                    base_c = rc(tid2, seq2)
                    if base_c >= INFEAS:
                        continue
                    base_m = moved_sum(tid2, seq2)
                    old = base_c + base_m
                    add_m = moved_cost(v, tid2)
                    for pos in range(len(seq2) + 1):
                        ns = seq2[:pos] + [v] + seq2[pos:]
                        nc = rc(tid2, ns)
                        if nc >= INFEAS:
                            continue
                        delta = (nc + base_m + add_m) - old - pen[v]
                        if bv is None or delta < bv[0]:
                            bv = (delta, tid2, ns)
                d[(v, tid)] = bv
        return d

    def try_eject(plan, u, max_drop, re_delta):
        if not time_left():
            return None
        u_pen = pen[u]
        skill = jskill[u]
        best = None
        for tid in healthy_ids:
            if skill not in tech_skills[tid]:
                continue
            seq = plan[tid]
            n = len(seq)
            if n == 0:
                continue
            base_c = rc(tid, seq)
            if base_c >= INFEAS:
                continue
            base_m = moved_sum(tid, seq)
            old = base_c + base_m
            combos = [(i,) for i in range(n)]
            if max_drop >= 2:
                for i in range(n):
                    for j in range(i + 1, n):
                        combos.append((i, j))
            if max_drop >= 3 and n <= 8:
                for i in range(n):
                    for j in range(i + 1, n):
                        for k in range(j + 1, n):
                            combos.append((i, j, k))
            for combo in combos:
                if not time_left():
                    return best
                ok = True
                for i in combo:
                    if is_em[seq[i]]:
                        ok = False
                        break
                if not ok:
                    continue
                cs = set(combo)
                v_pen = 0.0
                tot_re = 0.0
                for i in combo:
                    v = seq[i]
                    v_pen += pen[v]
                    rd = re_delta.get((v, tid))
                    if rd is not None and rd[0] < -1e-9:
                        tot_re += rd[0]
                base = [seq[i] for i in range(n) if i not in cs]
                add_m = moved_cost(u, tid)
                bm = moved_sum(tid, base)
                for pos in range(len(base) + 1):
                    ns = base[:pos] + [u] + base[pos:]
                    nc = rc(tid, ns)
                    if nc >= INFEAS:
                        continue
                    tot = (nc + bm + add_m) - old - u_pen + v_pen + tot_re
                    if tot < -1e-9 and (best is None or tot < best[0]):
                        best = (tot, tid, ns, [seq[i] for i in combo])
        return best

    def apply_eject(plan, tid, ns, victims):
        plan[tid] = ns
        for v in victims:
            bv = None
            skill = jskill[v]
            for tid2 in healthy_ids:
                if tid2 == tid:
                    continue
                if skill not in tech_skills[tid2]:
                    continue
                seq2 = plan[tid2]
                base_c = rc(tid2, seq2)
                if base_c >= INFEAS:
                    continue
                base_m = moved_sum(tid2, seq2)
                old = base_c + base_m
                add_m = moved_cost(v, tid2)
                for pos in range(len(seq2) + 1):
                    n2 = seq2[:pos] + [v] + seq2[pos:]
                    nc = rc(tid2, n2)
                    if nc >= INFEAS:
                        continue
                    delta = (nc + base_m + add_m) - old - pen[v]
                    if delta < -1e-9 and (bv is None or delta < bv[0]):
                        bv = (delta, tid2, n2)
            if bv is not None:
                plan[bv[1]] = bv[2]

    def coverage(plan):
        while time_left():
            sched = set()
            for tid in healthy_ids:
                sched.update(plan[tid])
            unsched = [j for j in all_ids if j not in sched]
            if not unsched:
                return
            unsched.sort(key=lambda j: (-priority[j], j))
            improved = False
            for u in unsched:
                r = best_insertion(plan, u)
                if r is not None and r[0] < -1e-9:
                    plan[r[1]] = r[2]
                    improved = True
                    break
            if improved:
                continue
            re_delta = compute_reinsert_deltas(plan)
            for u in unsched:
                if not time_left():
                    return
                r = try_eject(plan, u, 2, re_delta)
                if r is not None:
                    apply_eject(plan, r[1], r[2], r[3])
                    improved = True
                    break
            if improved:
                continue
            for u in unsched:
                if not time_left():
                    return
                r = try_eject(plan, u, 3, re_delta)
                if r is not None:
                    apply_eject(plan, r[1], r[2], r[3])
                    improved = True
                    break
            if improved:
                continue
            return

    # ------------------------------------------------------------------
    # local search (champion's moves)
    # ------------------------------------------------------------------
    def try_relocate(plan):
        for tida in healthy_ids:
            sa = plan[tida]
            if not sa:
                continue
            ca = tech_cost(tida, sa)
            if ca >= INFEAS:
                continue
            ma = moved_sum(tida, sa)
            for i in range(len(sa)):
                if not time_left():
                    return False
                jid = sa[i]
                na = sa[:i] + sa[i + 1:]
                nca = rc(tida, na)
                if nca >= INFEAS:
                    continue
                costa = nca + ma - moved_cost(jid, tida)
                da = costa - ca
                skill = jskill[jid]
                for tidb in healthy_ids:
                    if tidb == tida:
                        continue
                    if skill not in tech_skills[tidb]:
                        continue
                    sb = plan[tidb]
                    cb = tech_cost(tidb, sb)
                    if cb >= INFEAS:
                        continue
                    mb = moved_sum(tidb, sb)
                    add_m = moved_cost(jid, tidb)
                    for pos in range(len(sb) + 1):
                        nb = sb[:pos] + [jid] + sb[pos:]
                        ncb = rc(tidb, nb)
                        if ncb >= INFEAS:
                            continue
                        if da + ((ncb + mb + add_m) - cb) < -1e-9:
                            plan[tida] = na
                            plan[tidb] = nb
                            return True
        return False

    def try_swap(plan):
        for ai in range(len(healthy_ids)):
            tida = healthy_ids[ai]
            sa = plan[tida]
            if not sa:
                continue
            ca = tech_cost(tida, sa)
            if ca >= INFEAS:
                continue
            ma = moved_sum(tida, sa)
            for bi in range(ai + 1, len(healthy_ids)):
                tidb = healthy_ids[bi]
                sb = plan[tidb]
                if not sb:
                    continue
                cb = tech_cost(tidb, sb)
                if cb >= INFEAS:
                    continue
                mb = moved_sum(tidb, sb)
                for i in range(len(sa)):
                    if not time_left():
                        return False
                    ja = sa[i]
                    if jskill[ja] not in tech_skills[tidb]:
                        continue
                    for j in range(len(sb)):
                        jb = sb[j]
                        if jskill[jb] not in tech_skills[tida]:
                            continue
                        na = sa[:i] + [jb] + sa[i + 1:]
                        nb = sb[:j] + [ja] + sb[j + 1:]
                        nca = rc(tida, na)
                        if nca >= INFEAS:
                            continue
                        ncb = rc(tidb, nb)
                        if ncb >= INFEAS:
                            continue
                        costa = nca + ma - moved_cost(ja, tida) + moved_cost(jb, tida)
                        costb = ncb + mb - moved_cost(jb, tidb) + moved_cost(ja, tidb)
                        if (costa - ca) + (costb - cb) < -1e-9:
                            plan[tida] = na
                            plan[tidb] = nb
                            return True
        return False

    def try_2opt(plan):
        for ai in range(len(healthy_ids)):
            tida = healthy_ids[ai]
            sa = plan[tida]
            if not sa:
                continue
            ca = tech_cost(tida, sa)
            if ca >= INFEAS:
                continue
            for bi in range(ai + 1, len(healthy_ids)):
                tidb = healthy_ids[bi]
                sb = plan[tidb]
                if not sb:
                    continue
                cb = tech_cost(tidb, sb)
                if cb >= INFEAS:
                    continue
                for i in range(len(sa) + 1):
                    if not time_left():
                        return False
                    head_a = sa[:i]
                    tail_a = sa[i:]
                    ok = True
                    for x in tail_a:
                        if jskill[x] not in tech_skills[tidb]:
                            ok = False
                            break
                    if not ok:
                        continue
                    for j in range(len(sb) + 1):
                        tail_b = sb[j:]
                        ok2 = True
                        for x in tail_b:
                            if jskill[x] not in tech_skills[tida]:
                                ok2 = False
                                break
                        if not ok2:
                            continue
                        na = head_a + tail_b
                        nb = sb[:j] + tail_a
                        nca = rc(tida, na)
                        if nca >= INFEAS:
                            continue
                        ncb = rc(tidb, nb)
                        if ncb >= INFEAS:
                            continue
                        costa = nca + moved_sum(tida, na)
                        costb = ncb + moved_sum(tidb, nb)
                        if (costa - ca) + (costb - cb) < -1e-9:
                            plan[tida] = na
                            plan[tidb] = nb
                            return True
        return False

    def try_or_opt(plan):
        for tid in healthy_ids:
            seq = plan[tid]
            n = len(seq)
            if n < 3:
                continue
            old = tech_cost(tid, seq)
            if old >= INFEAS:
                continue
            ms = moved_sum(tid, seq)
            best = None
            for seglen in (1, 2, 3):
                for i in range(n - seglen + 1):
                    if not time_left():
                        if best is not None:
                            plan[tid] = best[1]
                            return True
                        return False
                    seg = seq[i:i + seglen]
                    rest = seq[:i] + seq[i + seglen:]
                    for pos in range(len(rest) + 1):
                        if pos == i:
                            continue
                        ns = rest[:pos] + seg + rest[pos:]
                        nc = rc(tid, ns)
                        if nc >= INFEAS:
                            continue
                        c = nc + ms
                        if c < old - 1e-9 and (best is None or c < best[0]):
                            best = (c, ns)
            if best is not None:
                plan[tid] = best[1]
                return True
        return False

    def local_search(plan):
        while time_left():
            if try_relocate(plan):
                continue
            if try_swap(plan):
                continue
            if try_2opt(plan):
                continue
            if try_or_opt(plan):
                continue
            break

    # ------------------------------------------------------------------
    # emergency-first seed
    # ------------------------------------------------------------------
    emergencies = [j for j in all_ids if is_em[j]]
    em_sorted = sorted(emergencies, key=lambda j: (-priority[j], j))

    plan = {tid: [] for tid in healthy_ids}
    if emergencies:
        m = len(em_sorted)
        best_plan = [None]
        best_cost = [float("inf")]

        def dfs(idx, acc):
            if acc >= best_cost[0] or not time_left():
                return
            if idx == m:
                best_cost[0] = acc
                best_plan[0] = {tid: list(s) for tid, s in plan.items()}
                return
            jid = em_sorted[idx]
            for tid in elig[jid]:
                seq = plan[tid]
                bg = rc(tid, seq) + moved_sum(tid, seq)
                for pos in range(len(seq) + 1):
                    ns = seq[:pos] + [jid] + seq[pos:]
                    nc = rc(tid, ns)
                    if nc >= INFEAS:
                        continue
                    d = (nc + moved_sum(tid, seq) + moved_cost(jid, tid)) - bg
                    plan[tid] = ns
                    dfs(idx + 1, acc + d)
                    plan[tid] = seq

        dfs(0, 0.0)
        if best_plan[0] is not None:
            for tid in healthy_ids:
                plan[tid] = best_plan[0][tid]

    for _round in range(6):
        if not time_left():
            break
        coverage(plan)
        local_search(plan)
        sched = set()
        for tid in healthy_ids:
            sched.update(plan[tid])
        if all(j in sched for j in all_ids):
            break

    best_plan = {tid: list(plan[tid]) for tid in healthy_ids}
    best_cost = total_cost(best_plan)

    # ------------------------------------------------------------------
    # deterministic ILS: swap / move / ruin perturbations + re-optimise
    # ------------------------------------------------------------------
    rng = [987654321]

    def rnd(n):
        rng[0] = (rng[0] * 1103515245 + 12345) & 0x7fffffff
        return rng[0] % n

    it = 0
    while time_left():
        it += 1
        plan = {tid: list(best_plan[tid]) for tid in healthy_ids}
        mode = it % 3

        if mode == 0:
            # swap two scheduled jobs between two techs
            sched = [(tid, j) for tid in healthy_ids for j in plan[tid]]
            if len(sched) >= 2:
                a = rnd(len(sched))
                b = rnd(len(sched))
                if a != b:
                    ta, ja = sched[a]
                    tb, jb = sched[b]
                    if (ta != tb
                            and jskill[ja] in tech_skills[tb]
                            and jskill[jb] in tech_skills[ta]):
                        if ja in plan[ta]:
                            plan[ta].remove(ja)
                        if jb in plan[tb]:
                            plan[tb].remove(jb)
                        plan[ta].append(jb)
                        plan[tb].append(ja)
        elif mode == 1:
            # move one scheduled job to another eligible tech
            sched = [(tid, j) for tid in healthy_ids for j in plan[tid]]
            if sched:
                a = rnd(len(sched))
                ta, ja = sched[a]
                cands = [tid for tid in healthy_ids
                         if tid != ta and jskill[ja] in tech_skills[tid]]
                if cands:
                    tb = cands[rnd(len(cands))]
                    if ja in plan[ta]:
                        plan[ta].remove(ja)
                    plan[tb].append(ja)
        else:
            # ruin: drop a few non-emergency jobs
            sched = [(tid, j) for tid in healthy_ids
                     for j in plan[tid] if not is_em[j]]
            k = 1 + (it % 3)
            for _ in range(min(k, len(sched))):
                if not sched:
                    break
                a = rnd(len(sched))
                ta, ja = sched.pop(a)
                if ja in plan[ta]:
                    plan[ta].remove(ja)

        # repair any infeasible routes the perturbation created
        for tid in healthy_ids:
            seq = plan[tid]
            if seq and rc(tid, seq) >= INFEAS:
                kept, _dropped = drop_until_feasible(state, tech_by_id[tid], seq)
                plan[tid] = kept

        coverage(plan)
        local_search(plan)
        c = total_cost(plan)
        if c < best_cost - 1e-9:
            best_cost = c
            best_plan = {tid: list(plan[tid]) for tid in healthy_ids}

    # ------------------------------------------------------------------
    # safety net: every emergency must be assigned
    # ------------------------------------------------------------------
    sched = set()
    for tid in healthy_ids:
        sched.update(best_plan[tid])
    for jid in emergencies:
        if jid in sched:
            continue
        best = None
        for tid in elig[jid]:
            seq = best_plan[tid]
            for pos in range(len(seq) + 1):
                ns = seq[:pos] + [jid] + seq[pos:]
                nc = rc(tid, ns)
                if nc >= INFEAS:
                    continue
                if best is None or nc < best[0]:
                    best = (nc, tid, ns)
        if best is None:
            for tid in elig[jid]:
                seq = best_plan[tid]
                for pos in range(len(seq) + 1):
                    ns = seq[:pos] + [jid] + seq[pos:]
                    nc = rc(tid, ns)
                    if best is None or nc < best[0]:
                        best = (nc, tid, ns)
        if best is not None:
            best_plan[best[1]] = best[2]
            sched.add(jid)

    for tid in healthy_ids:
        result[tid] = best_plan[tid]
    return result
